var i=251;var a=`251-north-african-spices-and-cooking-techniques`;var o=`240`;var n={en:`North African Spices and Cooking Techniques`,ua:`Північноафриканські спеції та методи приготування`};var s={short:`North African cuisines use spice mixtures, grains, legumes, vegetables and moist cooking to produce aromatic, satisfying dishes. Learning their techniques means understanding regional differences among Morocco, Algeria, Tunisia and neighboring countries rather than memorizing a single tagine recipe.`,sections:[{title:`Core idea`,text:`In Maghrebi cooking, couscous and semolina preparations often accompany vegetable or meat stews. Tagines refer both to cooking vessels and dishes, and the name does not imply one universal combination of spices.`},{title:`Scientific / practical principles`,text:`Steaming semolina develops texture without flooding it; gradual hydration helps grains remain separate. Covered simmering conserves moisture, while spices such as cumin, coriander, cinnamon or saffron are chosen for a particular regional dish, not automatically added together.`},{title:`How to apply it`,text:`Practice preparing couscous according to its product type, then pair it with a vegetable stew. Make a modest aromatic base and add spices in stages; check liquid reduction, tenderness and seasoning.`},{title:`Practical example`,text:`Prepare two small portions of couscous, one properly hydrated and steamed and one soaked with excessive water. Compare texture and decide how much sauce each absorbs.`},{title:`Common mistakes and limitations`,text:`Do not treat instant couscous as identical to traditionally hand-rolled and steamed semolina. Cooking techniques and flavorings vary across communities, and a covered pot is not proof that food has reached a safe internal temperature.`},{title:`Related theories`,text:`063, 081, 086, 112.`}]};var r={short:`У північноафриканських кухнях спеції, крупи, бобові, овочі та вологі методи приготування створюють ароматні ситні страви. Важливо розуміти відмінності Марокко, Алжиру, Тунісу та інших країн, а не запам’ятати один рецепт тажину.`,sections:[{title:`Суть`,text:`У кухнях Магрибу кускус та інші страви з манної крупи часто подають із тушкованими овочами чи м’ясом. Тажин є і посудом, і назвою страви, але не універсальною сумішшю спецій.`},{title:`Наукові та практичні принципи`,text:`Обробка кускусу парою формує текстуру без надлишку води; поступове зволоження допомагає зернам залишатися розсипчастими. Тушкування під кришкою зменшує втрати вологи, а кмин, коріандр, корицю чи шафран добирають до конкретного місцевого рецепта.`},{title:`Як застосовувати`,text:`Освойте приготування кускусу відповідно до його виду й подайте його з овочевим рагу. Створіть помірну ароматичну основу, додавайте спеції поетапно та перевіряйте густоту, м’якість і смак.`},{title:`Практичний приклад`,text:`Приготуйте дві невеликі порції кускусу: одну правильно зволожену та оброблену парою, іншу приготуйте з надлишком води. Порівняйте текстуру й поглинання соусу.`},{title:`Поширені помилки та обмеження`,text:`Кускус швидкого приготування не тотожний традиційному вручну сформованому та пропареному. Рецепти й аромати суттєво різняться; закрита кришка також не гарантує безпечної температури всередині м’яса.`},{title:`Пов’язані теорії`,text:`063, 081, 086, 112.`}]};var c=[63,81,86,112];var d=`Sources / Джерела`;var l=[`https://ich.unesco.org/en/RL/knowledge-know-how-and-practices-pertaining-to-the-production-and-consumption-of-couscous-01602?RL=01602&lang=en`,`https://ich.unesco.org/en/decisions/5.com/6.41`];var u={id:251,slug:a,group:`240`,title:n,en:s,ua:r,related:c,referenceTitle:d,references:l};export{u as default,s as en,o as group,i as id,d as referenceTitle,l as references,c as related,a as slug,n as title,r as ua};